entries[7365] = { ["name"] = "Flasche Gift", ["text"] = "Nahkampfreichweite\nSofort 1 min Abklingzeit\nWirft eine Flasche Gift auf den Feind und fügt ihm 30 Sek. lang alle 3 Sek. 19 Punkt(e) Naturschaden zu." }
entries[7366] = { ["name"] = "Berserkerhaltung", ["text"] = "Sofort\nNimmt eine aggressive Haltung ein, die Wut erzeugt, wenn der Krieger einen Gegner schlägt. Hält 4 Min. lang an." }
entries[7367] = { ["name"] = "Infizierter Biss", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht alle 10 Sek. 15 Punkt(e) Naturschaden bei einem Feind und erhöht seinen erlittenen körperlichen Schaden um 5 Punkt(e). Hält 3 Min. lang an." }
entries[7369] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin weit reichender Angriff, der dem Ziel und seinem nächsten Verbündeten Euren Waffenschaden sowie 10 zusätzlichen Schaden zufügt." }
entries[7370] = { ["name"] = "Sturmangriff" }
entries[7371] = { ["name"] = "Sturmangriff", ["text"] = "35 Fokus 8 - 25 Meter Reichweite\nSpontanzauber 25 sek. Abklingzeit\nAuf einen Feind zustürmen, wobei er 1 Sek. lang bewegungsunfähig wird und außerdem die Nahkampfangriffskraft des Ebers beim nächsten Angriff um 60 erhöht wird." }
entries[7372] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, wobei 18 Punkt(e) Schaden verursacht werden und die Bewegung des Feindes 15 Sek. lang auf 45% des normalen Tempos verlangsamt wird." }
