entries[7379] = { ["name"] = "Rache", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Verteidigungshaltung\nFührt einen sofortigen Gegenangriff gegen den Feind aus, der 25 bis 31 Punkt(e) Schaden verursacht und dabei ein hohes Maß an Bedrohung generiert. 'Rache' muss auf Blocken, Ausweichen oder Parieren folgen." }
